#!/usr/bin/env python3
"""Make a local, offline atlas from frozen manual observations and checked results."""
import html
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]

def main():
    ann=json.loads((ROOT/'data/round14_manual_annotations.json').read_text())
    summary=json.loads((ROOT/'data/round14_summary.json').read_text())
    arithmetic=json.loads((ROOT/'data/round14_arithmetic_checks.json').read_text())
    editorial=(ROOT/'data/round14_editorial_cells.csv').read_text(encoding='utf-8-sig')
    # JSON is embedded to keep the file usable over file:// without fetch/CORS.
    data=json.dumps(ann,ensure_ascii=False).replace('</','<\\/')
    page='''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Три таблички — графический атлас и арифметические проверки</title><style>
body{font:17px/1.6 system-ui,sans-serif;max-width:1180px;margin:auto;padding:26px 22px;background:#f4f1e9;color:#223740}h1,h2{line-height:1.2}a{color:#135e73}button,select{font:inherit;padding:7px 10px;border:1px solid #9bafb4;border-radius:4px;background:white;color:#203a43}button{cursor:pointer}label{display:inline-flex;align-items:center;gap:6px}header p{max-width:960px}.toolbar{display:flex;gap:14px;align-items:center;flex-wrap:wrap;background:#e1eaeb;padding:14px;position:sticky;top:0;z-index:3}.note{background:#e6edec;padding:14px 18px}.stat{display:flex;gap:12px;flex-wrap:wrap}.stat span{background:white;border:1px solid #d0d8d7;padding:8px 14px}.viewer{background:white;padding:12px;margin-top:18px}svg{display:block;width:100%;height:auto;max-height:850px}#detail{padding:12px;border-left:4px solid #be5439;background:#fff8ec;min-height:64px}.scroll{overflow:auto;max-height:530px;border:1px solid #c4cecd}table{border-collapse:collapse;width:100%;background:white;font-size:14px}td,th{padding:9px;border:1px solid #cbd2d1;text-align:left;vertical-align:top}th{background:#dfe8e8;position:sticky;top:0}td button{font-size:13px;padding:3px 5px}code,pre{font-size:.94em}pre{white-space:pre-wrap;background:white;padding:16px;border:1px solid #d1d9d7;max-height:430px;overflow:auto}.equation{font-size:27px;font-weight:650;letter-spacing:.02em}figure{margin:20px 0;background:white;padding:14px}figure img{max-width:100%;height:auto}figcaption{font-size:14px;color:#50646d}.muted{font-size:14px;color:#50646d}@media print{.toolbar{position:static}.scroll{max-height:none;overflow:visible}button{display:none}svg{max-height:650px}}
</style></head><body><header><h1>Три таблички: графика и проверяемая арифметика</h1><p>25 октября2026 · Комплексный исследовательский цикл14. Фотография, графическая группировка, редакторское чтение и числовая модель показаны раздельно.</p><p><a href="observations/2026-10-25_round14_integrated_result.txt">Полный отчёт</a> · <a href="data/round14_summary.json">Итоги и ограничения</a> · <a href="data/round14_visual_freeze.json">Фиксация до новых индивидуальных чтений</a></p></header>
<div class="stat"><span>3 физических предмета</span><span>5 фотографических видов</span><span>29 областей просмотра</span><span>60 кандидатных групп</span></div><p class="note">Кандидатная группа может содержать несколько знаков или вдавлений. Эти60 групп не объявлены60 графемами, буквами или словами. Часть границ остаётся спорной. Музейные заголовки были известны заранее; полной смысловой слепоты нет.</p>
<h2>Разметка исходных фотографий</h2><div class="toolbar"><label>Вид <select id="view"></select></label><label>Семейство <select id="family"><option value="all">Все кандидаты</option></select></label><label><input id="regions" type="checkbox">Области просмотра</label><label><input id="boxes" type="checkbox" checked>Рамки групп</label><label><input id="labels" type="checkbox" checked>ID групп</label></div><div class="viewer"><svg id="picture" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Фотография с переключаемой графической разметкой"></svg></div><p id="viewinfo" class="muted"></p><p id="detail">Нажмите на рамку или ID группы в таблице. Выключите рамки для просмотра чистой фотографии.</p><p class="muted">B1 — ветвистая форма; R1 — округлые следы; V1 — контуры с внутренними штрихами; A1 — угловатые штрихи. F1/W1/W2 введены после просмотра новых изображений как поисковые категории. X — неразобранная область, а не один тип знака. SEAL — изобразительные следы, отделённые от линейного письма.</p><div class="scroll"><table><thead><tr><th>ID</th><th>Группа</th><th>Наблюдение</th><th>Единица</th><th>Число видимых следов, если ясно</th></tr></thead><tbody id="rows"></tbody></table></div>
<h2>Проверка на других предметах</h2><table><tr><th>Предмет</th><th>Округлые следыR1</th><th>Ветвистая формаB1</th><th>Граница вывода</th></tr><tr><td>1988.433.1</td><td>Наблюдаются</td><td>Наблюдается</td><td>Сходство графического семейства; звучание не назначено</td></tr><tr><td>1988.433.3</td><td>Наблюдаются</td><td>Не обнаружена на двух показанных видах</td><td>Отрицательный результат сохранён; не относится ко всему языку</td></tr></table>
<h2>Первая условная числовая проверка</h2><p>Для P005390 предполагается, что запись reverse1.1.a — итог, а1.1.b1 и1.1.b2 — составляющие. Это предпосылка, которую нужно проверять по расположению и другим документам.</p><pre>Итог:       2·N45 + 5·N14 + 3·N01
Часть1:     1·N45 + 7·N14
Часть2:             8·N14 + 3·N01

Если итог = часть1 + часть2, то вес(N45) = 10·вес(N14).</pre><p>При весах моделиŠE: N01=1, N14=6, N45=60:</p><p class="equation">153 = 102 + 51</p><p>При весах моделиS: N01=1, N14=10, N45=3600, сумма не сходится:7253 ≠3670+83. Это различает две модели при принятой предпосылке итог/части. ОтношениеN14/N01 не выведено из одной таблички — оно взято из внешней модели.</p>
<h2>Вторая проверка без назначения числовых весов</h2><p>На другом предмете, P005366, состав редакторских числовых классов сохраняет точную сумму:</p><pre>obverse1.1.b:   2·N18
obverse1.2.b:   4·N03 + 1·N40
reverse1.2:    2·N18 + 4·N03 + 1·N40

2A + (4B + C) = 2A + 4B + C</pre><p class="note">Это проверка структуры конкретных записей. Успех равенства не означает, что независимо установлено чтение каждого клина, название товара или язык писца. Алфавит и полный перевод не получены.</p>
<h2>Отдельный слой редакторской записи</h2><p>26 ячеек трёх предметов. N-обозначения — современные каталожные метки графики. Они не произносятся как древние слова.</p><pre>EDITORIAL</pre>
<h2>Различение фотографии и прорисовки</h2><figure><img src="sources/Met329081_view2.jpg" alt="Современная прорисовка сюжета печати"><figcaption>Второй файл изAPI Met329081 оказался прорисовкой печати1315×358. Он не использован как ещё одна фотография знаков. Изображение не подменялось подходящим снимком.</figcaption></figure>
<h2>Файлы и источники</h2><ul><li><a href="data/round14_graphic_candidates.csv">60 графических кандидатов</a> и <a href="data/round14_panels.csv">29 областей</a></li><li><a href="data/round14_arithmetic_checks.json">Предпосылки, веса и арифметика</a></li><li><a href="data/round14_verified_identity.csv">Проверенные музейные идентификаторы</a></li><li><a href="data/round14_model_assessment.csv">Сравнение моделей письма</a></li><li><a href="https://www.metmuseum.org/art/collection/search/329081">1988.433.1</a>, <a href="https://www.metmuseum.org/art/collection/search/327384">1988.433.2</a>, <a href="https://www.metmuseum.org/art/collection/search/327385">1988.433.3</a></li><li><a href="https://cdli.earth/files-up/publications/englund2004a.pdf">Englund2004</a>, целевые схемы на печатных с.32–33, рисунки4a–4b. Схемы — современная реконструкция, с которой сравниваются данные.</li></ul><p>Фотографии музея отмечены как public domain. Книга не изменялась. Версия K0→шумерский остаётся открытой: независимой фонетической цепочки для её проверки этот проход не восстановил.</p>
<script>const DATA=DATAJSON;
const ns='http://www.w3.org/2000/svg',byId=id=>document.getElementById(id);
let selected='';
const names={T0A:'1988.433.2 — видA (опорный)',T0B:'1988.433.2 — видB (опорный)',T1A:'1988.433.1 — фото',T2A:'1988.433.3 — видA',T2B:'1988.433.3 — видB'};
for(const v of DATA.views){const o=document.createElement('option');o.value=v.id;o.textContent=names[v.id];byId('view').append(o)}
for(const f of [...new Set(DATA.views.flatMap(v=>v.candidates.map(g=>g.family)))].sort()){const o=document.createElement('option');o.value=f;o.textContent=f;byId('family').append(o)}
function element(tag,attrs,text){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text)e.textContent=text;return e}
function show(g){selected=g.id;byId('detail').textContent=g.id+' · '+g.description+' · Границы '+(g.boundary_uncertain?'не окончательные':'отчётливо различимого набора следов')+'; звук и значение не назначены.';render()}
function render(){const v=DATA.views.find(v=>v.id===byId('view').value),svg=byId('picture'),family=byId('family').value;svg.replaceChildren();svg.setAttribute('viewBox','0 0 '+v.width+' '+v.height);svg.append(element('image',{href:v.image,width:v.width,height:v.height}));
const scale=b=>({x:b[0]*v.width/1000,y:b[1]*v.height/1000,width:(b[2]-b[0])*v.width/1000,height:(b[3]-b[1])*v.height/1000});
if(byId('regions').checked)for(const p of v.panels){const a=scale(p.box);svg.append(element('rect',{...a,fill:'none',stroke:'#14647c','stroke-width':3,'stroke-dasharray':'12 8'}));svg.append(element('text',{x:a.x+5,y:a.y+30,fill:'#083e57','font-size':29,'font-weight':'bold'},p.id))}
const groups=v.candidates.filter(g=>family==='all'||g.family===family);byId('rows').replaceChildren();
for(const g of groups){const a=scale(g.box);if(byId('boxes').checked){const rect=element('rect',{...a,fill:g.id===selected?'#ffe19b':'transparent','fill-opacity':(g.id===selected ? 0.22 : 0),stroke:g.id===selected?'#b11825':'#db622b','stroke-width':g.id===selected?7:3,'stroke-dasharray':g.boundary_uncertain?'10 6':'none'});rect.append(element('title',{},g.id+' '+g.description));rect.style.cursor='pointer';rect.onclick=()=>show(g);svg.append(rect)}if(byId('labels').checked){const label=element('text',{x:a.x+4,y:a.y+26,fill:'#962d13','font-size':27,'font-weight':'bold','paint-order':'stroke',stroke:'#fff8e8','stroke-width':3},g.id.split('-').pop()+' '+g.family);label.style.cursor='pointer';label.onclick=()=>show(g);svg.append(label)}const tr=document.createElement('tr');const first=document.createElement('td'),button=document.createElement('button');button.textContent=g.id;button.onclick=()=>show(g);first.append(button);tr.append(first);for(const val of[g.family,g.description,g.unit,g.visible_mark_count_if_clear===null||g.visible_mark_count_if_clear===''?'не задано':g.visible_mark_count_if_clear]){const td=document.createElement('td');td.textContent=val;tr.append(td)}byId('rows').append(tr)}
byId('viewinfo').textContent=v.id+' · '+v.width+'×'+v.height+' исходных пикселей кадра · '+v.image+' · '+(v.individual_editorial_text_known_before_image?'индивидуальное чтение уже было известно':'новые графические наблюдения зафиксированы до индивидуального чтения');}
for(const id of['view','family','regions','boxes','labels'])byId(id).addEventListener('change',render);byId('view').value='T1A';render();
</script></body></html>'''
    page=page.replace('EDITORIAL',html.escape(editorial)).replace('DATAJSON',data)
    (ROOT/'comparison_round14.html').write_text(page)
    print('Offline atlas written with embedded observations,5 views,filters and arithmetic audit.')

if __name__=='__main__':main()
